// src/landing/hero-globe.landMask.js
/**
 * Land mask of the hero globe: decode the run-length string generated by scripts/gen-landing-land-mask.mjs into a
 * 1-byte-per-cell equirectangular grid and answer "is this lat/lon land?".
 *
 * @module landing/hero-globe.landMask
 */

const RUN_DIGITS = 2;

/**
 * Decode `{ width, height, runs }`. `runs` holds, row by row, alternating water/land run lengths (water first, base 36,
 * two digits each); the runs of a row sum to `width`.
 * @param {{ width: number, height: number, runs: string }} source
 * @returns {{ width: number, height: number, cells: Uint8Array }} cells: 1 = land
 */
export function decodeLandMask({ width, height, runs }) {
  const cells = new Uint8Array(width * height);
  let cursor = 0;
  for (let row = 0; row < height; row++) {
    let col = 0;
    let land = false;
    while (col < width) {
      if (cursor >= runs.length) throw new Error(`Land mask truncated in row ${row} (${cursor} of ${runs.length} chars read)`);
      const length = Number.parseInt(runs.slice(cursor, cursor + RUN_DIGITS), 36);
      if (!Number.isInteger(length) || col + length > width) throw new Error(`Land mask run out of range in row ${row}`);
      cursor += RUN_DIGITS;
      if (land) cells.fill(1, row * width + col, row * width + col + length);
      col += length;
      land = !land;
    }
  }
  return { width, height, cells };
}

/**
 * @param {{ width: number, height: number, cells: Uint8Array }} mask
 * @param {number} lat degrees, -90..90
 * @param {number} lon degrees, -180..180
 * @returns {boolean}
 */
export function isLand(mask, lat, lon) {
  const col = Math.min(mask.width - 1, Math.max(0, Math.floor(((lon + 180) / 360) * mask.width)));
  const row = Math.min(mask.height - 1, Math.max(0, Math.floor(((90 - lat) / 180) * mask.height)));
  return mask.cells[row * mask.width + col] === 1;
}
